@media (max-width:400px){.card{padding:28px 20px 24px}h1{font-size:21px}}`;

const CHECK_ICON =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>';
const ALERT_ICON =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5"/><path d="M12 16.5h.01"/></svg>';

export function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

/**
 * Renders one self-contained Tui page — no external CSS, fonts, or images.
 *
 * `lead`, `steps`, and `hint` are trusted HTML so copy can carry `<code>`
 * spans; the title is escaped. Escape request-derived text at the call site.
 */
function arcadePage(
  tone: "ok" | "warn",
  title: string,
  lead: string,
  steps: string[],
  hint: string,
): string {
  const list = steps.length === 0
    ? ""
    : `<ul class="steps">${steps.map((step) => `<li>${step}</li>`).join("")}</ul>`;
  const hintHtml = hint ? `<p class="hint">${hint}</p>` : "";
  const icon = tone === "ok" ? CHECK_ICON : ALERT_ICON;
  const titleText = escapeHtml(title);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>Tui — ${titleText}</title>
<style>${STYLE}</style>
</head>
<body>
<main class="card" data-tone="${tone}">
<span class="badge">${icon}</span>
<p class="eyebrow">Tui</p>
<h1>${titleText}</h1>
<p class="lead">${lead}</p>
${list}
${hintHtml}
</main>
</body>
</html>`;
}

/** Success: the CLI has the token and is finishing the sign-in. */
export function signedInPage(): string {
  return arcadePage(
    "ok",
    "You're signed in",
    "Tui saved the session on this machine. You can close this tab and go back to your terminal.",
    [],
    "Run <code>gamepigeon auth status</code> any time to see which account is signed in.",
  );
}

/**
 * The handoff reached the listener but carried no usable session. `reason` is
 * trusted HTML — escape request-derived text with `escapeHtml` first.
 */
export function signInFailedPage(reason: string): string {
  return arcadePage(
    "warn",
    "Sign-in didn't finish",
    reason,
    [
      "Go back to your terminal and run <code>gamepigeon auth oauth google</code> (or <code>github</code>) again.",
      "If your browser blocked the redirect back to Tui, allow pop-ups for the login page.",
      "Approve the Google or GitHub consent screen rather than closing it.",
    ],
    "Prefer a password? <code>gamepigeon auth login</code> signs in the same account.",
  );
}

