    // default handler still gets the user to the login page.
    return runOpener("open", [url]) || runOpener("open", ["-a", "Safari", url]);
  }
  if (process.platform === "win32") {
    return runOpener("cmd", ["/c", "start", "", url])
      || runOpener("rundll32", ["url.dll,FileProtocolHandler", url]);
  }
  return runOpener("xdg-open", [url])
    || runOpener("gio", ["open", url])
    || runOpener("x-www-browser", [url]);
}

async function withTimeout<T>(promise: Promise<T>, ms: number, message: string): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(() => reject(new Error(message)), ms);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

function isOAuthProvider(value: string | undefined): value is OAuthProvider {
  return value !== undefined && (oauthProviders as readonly string[]).includes(value);
}

async function runOAuthLogin(provider: OAuthProvider): Promise<AuthSuccess> {
  const authBaseUrl = requireAuthBaseUrl();
  const callback = startOAuthCallbackServer(defaultCallbackPort);
  try {
    await callback.ready;
    // The nonce rides on the callback URL so the Worker hands it back to us;
    // this listener accepts any state (see docs/oauth-handoff-contract.md), but
    // sending one keeps the callback URL shaped like the overlay's.
    const next = `http://127.0.0.1:${callback.port}/auth/callback?state=${randomBytes(16).toString("hex")}`;
    const url = `${authBaseUrl}/cli/oauth?provider=${provider}&next=${encodeURIComponent(next)}`;
