    const label = provider === "google" ? "Google" : "GitHub";
    console.log(
      opened
        ? `Opening your browser to sign in with ${label}...`
        : `Could not open a browser automatically. Sign in with ${label} here:`,
    );
    console.log(`  ${url}`);
    console.log("Waiting for the browser to finish sign-in...");
    const token = await withTimeout(callback.token, oauthTimeoutMs, "Sign-in timed out. Try again.");
    const user = await resolveUser(token);
    saveSession(token, user);
    console.log(`Signed in as ${user.email}`);
    return { kind: "signed_in", method: provider, userId: user.id };
  } finally {
    callback.close();
  }
}

export type { AuthUser, StoredSession };

