/**
 * Reads one query parameter, tolerating both `&` and `?` separators: some
 * hosted redirects append `?token` onto a callback that already carried
 * `?state`, yielding `state=..?token=..`. Mirrors `query_param` in
 * `tauri/src/main.rs`.
 */
function queryParam(query: string, key: string): string | undefined {
  for (const pair of query.split(/[&?]/)) {
    const separator = pair.indexOf("=");
    if (separator < 0) continue;
    if (pair.slice(0, separator) !== key) continue;
    return pair.slice(separator + 1);
  }
  return undefined;
}

/**
 * Percent-decoding for human-readable query text (OAuth error descriptions).
 * Tokens deliberately skip this: they round-trip through the listener verbatim,
 * so a `+` or `%` inside a session token is never rewritten.
 */
function decodeQueryText(value: string): string {
  const spaced = value.replaceAll("+", " ");
  try {
    return decodeURIComponent(spaced);
  } catch {
    return spaced;
  }
}

/**
 * Turns a failed handoff (`?error=...`) into a sentence worth showing. Capped
 * because it lands in both the browser page and the terminal.
 */
function callbackFailure(query: string): string | null {
  const error = queryParam(query, "error");
  if (!error) return null;
  if (error === "access_denied") return "Sign-in was cancelled before it finished.";
  const description = decodeQueryText(queryParam(query, "error_description") ?? "");
  const message = description
    ? description
    : `The login page reported an error: ${decodeQueryText(error)}`;
  return message.slice(0, 200);
}

export interface OAuthCallbackServer {
  /** The port actually bound; only final once `ready` has resolved. */
  readonly port: number;
  /** Resolves once the socket is bound and accepting requests. */
  ready: Promise<void>;
  /** Resolves with the raw token from the callback, rejects on error/cancel. */
  token: Promise<string>;
  close(): void;
}

/**
 * The localhost listener the browser hands the session token back to. Returns
 * synchronously so callers can build the callback URL from `port` after
 * awaiting `ready`.
 *
 * Unlike the overlay's Rust equivalent (`handle_callback_connection`), which is
 * handed the nonce it generated, this listener has no nonce to compare against,
 * so `state` is accepted and ignored here and the token resolves raw and
 * unverified — verifying it against the auth backend is the caller's job. See
 * `docs/oauth-handoff-contract.md`.
 */
export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let boundPort = port;
  let settled = false;
  let resolveToken: (token: string) => void = () => {};
  let rejectToken: (error: Error) => void = () => {};
  const token = new Promise<string>((resolve, reject) => {
    resolveToken = (value) => {
      settled = true;
      resolve(value);
    };
    rejectToken = (error) => {
      settled = true;
      reject(error);
    };
  });
  // A caller that only pings the listener never awaits `token`; keep a failed
  // handoff from surfacing as an unhandled rejection. Callers that do await it
  // still see the rejection.
  token.catch(() => {});

  const server = createServer((request, response) => {
    const target = request.url ?? "/";
    const queryStart = target.indexOf("?");
    const path = queryStart < 0 ? target : target.slice(0, queryStart);
    const query = queryStart < 0 ? "" : target.slice(queryStart + 1);

    const reply = (status: number, contentType: string, body: string): void => {
      response.writeHead(status, {
        "content-type": contentType,
        "content-length": Buffer.byteLength(body),
        // Pages carry a session token in their URL — keep them out of caches
        // and out of the Referer sent to anything they link to.
        "cache-control": "no-store",
        "referrer-policy": "no-referrer",
      });
      response.end(body);
    };

    if (path === "/auth/ping") {
      // The readiness probe the login page uses to check the CLI is listening.
      reply(200, "text/plain; charset=utf-8", "ok");
      return;
    }
    if (path !== "/auth/callback") {
      reply(404, "text/plain; charset=utf-8", "not found");
      return;
    }
    // A login page that gave up hands back `error` instead of `token`; saying
    // why beats the generic "did not return a session token".
    const failure = callbackFailure(query);
    if (failure) {
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(failure)));
      rejectToken(new Error(failure));
      return;
    }
    const value = queryParam(query, "token");
    if (!value) {
      const reason = "The login page came back without a session token.";
      reply(400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(reason)));
      rejectToken(new Error(reason));
      return;
    }
    reply(200, "text/html; charset=utf-8", signedInPage());
    resolveToken(value);
  });

  let retried = false;
  const ready = new Promise<void>((resolve, reject) => {
    server.on("error", (error: NodeJS.ErrnoException) => {
      // The overlay or an earlier attempt may already hold the default port;
      // an OS-assigned one still works, since the callback URL carries it.
      if (error.code === "EADDRINUSE" && !retried) {
        retried = true;
        server.listen(0, "127.0.0.1");
        return;
      }
      const failure = new Error(`Could not start the sign-in listener: ${error.message}`);
      reject(failure);
      if (!settled) rejectToken(failure);
    });
    server.once("listening", () => {
      const address = server.address();
      if (address && typeof address === "object") boundPort = address.port;
      resolve();
    });
    server.listen(port, "127.0.0.1");
  });
  // Same reasoning as `token`: a caller may only await one of the two.
  ready.catch(() => {});

  return {
    get port() {
      return boundPort;
    },
    ready,
    token,
    close() {
      // Browsers keep the callback socket alive, which would otherwise hold the
      // process open after the token has been handed over.
      server.closeAllConnections?.();
      server.close();
    },
  };
}

/**
 * Arc (and Dia, same vendor) route links from other apps into a "Little Arc"
 * window, which drops the login page's redirect chain — the tab either never
 * appears or dies mid-handoff, so sign-in silently never completes. Asking Arc
 * for a real tab in a real window over AppleScript bypasses Little Arc
 * entirely. Mirrors `is_arc_bundle` in `tauri/src/main.rs`.
 */
export function isArcBundle(bundleId: string): boolean {
  const id = bundleId.toLowerCase();
  return id === "company.thebrowser.browser" || id === "company.thebrowser.dia";
}

function applescriptEscape(value: string): string {
  return value.replaceAll("\\", "\\\\").replaceAll('"', '\\"');
}

/** The AppleScript that opens `url` as a real tab in a real Arc/Dia window. */
export function arcTabScript(bundleId: string, url: string): string {
  return `tell application id "${applescriptEscape(bundleId)}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
    tell front window to make new tab with properties {URL:"${applescriptEscape(url)}"}
