/**
 * The pages a CLI sign-in lands on while it is still inside the Worker: the
 * self-redirecting handoff page that carries the session token back to the
 * loopback listener, and the pages explaining why a handoff could not happen.
 *
 * The same design is rendered by `tauri/src/auth_pages.rs` and
 * `src/auth-pages.ts`; the three copies exist because they run in three
 * different runtimes. Keep the copy and palette in sync when changing one.
 */

const STYLE = `:root{color-scheme:light}
*{box-sizing:border-box}
body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;
background:radial-gradient(900px 500px at 50% -20%,#fff 0%,#eef2f8 60%,#e3eaf4 100%);color:#0f172a;
font:15px/1.6 system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",sans-serif;-webkit-font-smoothing:antialiased}
.card{position:relative;overflow:hidden;width:min(100%,420px);padding:34px 28px 30px;text-align:center;
background:#fff;border:1px solid #e2e8f0;border-radius:16px;
box-shadow:0 20px 50px rgba(15,23,42,.12),0 8px 20px rgba(15,23,42,.06)}
.card::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;
background:linear-gradient(90deg,#2955c9 0%,#3772ff 38%,#3bb273 72%,#e6a830 100%)}
.badge{display:flex;align-items:center;justify-content:center;width:44px;height:44px;margin:0 auto 16px;border-radius:999px}
.badge svg{width:22px;height:22px}
[data-tone=ok] .badge{background:rgba(59,178,115,.14);color:#2e8f5c}
[data-tone=warn] .badge{background:rgba(223,41,53,.12);color:#b81f2a}
.eyebrow{margin:0 0 6px;font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#2955c9}
h1{margin:0 0 10px;font-size:23px;line-height:1.25;letter-spacing:-.01em}
.lead{margin:0;color:#475569}
.steps{margin:18px 0 0;padding:0;list-style:none;text-align:left;border-top:1px solid #e2e8f0}
.steps li{position:relative;margin:0;padding:10px 0 0 18px;font-size:13.5px;color:#475569}
.steps li:first-child{padding-top:14px}
.steps li::before{content:"";position:absolute;left:2px;top:18px;width:5px;height:5px;border-radius:999px;background:#cbd5e1}
.steps li:first-child::before{top:22px}
.hint{margin:16px 0 0;font-size:12.5px;color:#64748b}
code{font:600 12.5px/1.4 ui-monospace,"SF Mono",Menlo,monospace;background:#f3f6fb;border:1px solid #e2e8f0;border-radius:5px;padding:2px 5px;overflow-wrap:anywhere;-webkit-box-decoration-break:clone;box-decoration-break:clone}
@media (max-width:400px){.card{padding:28px 20px 24px}h1{font-size:21px}}`;

const CHECK_ICON =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>';
const ALERT_ICON =
  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5"/><path d="M12 16.5h.01"/></svg>';

export function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

interface PageParts {
  tone: "ok" | "warn";
  title: string;
  /** Trusted HTML so copy can carry `<code>` spans; escape request text first. */
  lead: string;
  steps?: string[];
  hint?: string;
  /** Extra trusted markup for `<head>`, e.g. a `<meta http-equiv=refresh>`. */
  head?: string;
  /** Extra trusted markup at the end of `<body>`, e.g. a redirect script. */
  tail?: string;
}

/** Renders one self-contained Tui page — no external CSS, fonts, or images. */
function arcadePage(parts: PageParts): string {
  const steps = parts.steps ?? [];
  const list = steps.length === 0
    ? ""
    : `<ul class="steps">${steps.map((step) => `<li>${step}</li>`).join("")}</ul>`;
  const hint = parts.hint ? `<p class="hint">${parts.hint}</p>` : "";
  const icon = parts.tone === "ok" ? CHECK_ICON : ALERT_ICON;
  const title = escapeHtml(parts.title);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<meta name="referrer" content="no-referrer">
<title>Tui — ${title}</title>
${parts.head ?? ""}
<style>${STYLE}</style>
</head>
<body>
<main class="card" data-tone="${parts.tone}">
<span class="badge">${icon}</span>
<p class="eyebrow">Tui</p>
<h1>${title}</h1>
<p class="lead">${parts.lead}</p>
${list}
${hint}
</main>
${parts.tail ?? ""}
</body>
</html>`;
}

/**
 * Embeds `value` as a JavaScript string literal. `<` is escaped so a token that
 * somehow contained `</script>` cannot end the element early; every character a
 * loopback callback URL actually uses survives verbatim, which is what the CLI
 * listener needs (see `docs/oauth-handoff-contract.md`).
 */
function jsString(value: string): string {
  return JSON.stringify(value).replaceAll("<", "\\u003c");
}

/**
 * Hands the browser's session back to the CLI listener at `url`. The redirect
 * happens in the page rather than as a `302` so the browser keeps a real
 * document here: the loopback listener answers exactly once, and a cached or
 * re-followed redirect would spend the handoff on a tab the CLI is not waiting
 * on. The `<meta refresh>` copy covers scripting being disabled.
 */
export function handoffRedirectPage(url: string): string {
  const escaped = escapeHtml(url);
  return arcadePage({
    tone: "ok",
    title: "Finishing sign-in",
    lead: "Handing your session back to the terminal. This tab will move along on its own.",
    steps: [`Not moving? <a href="${escaped}">Continue to Tui</a>.`],
    hint: "You can close this tab once your terminal says you're signed in.",
    head: `<meta http-equiv="refresh" content="0;url=${escaped}">`,
    tail: `<script>location.replace(${jsString(url)})</script>`,
  });
}

/** The browser reached the handoff without a signed-in session to hand over. */
export function signInRequiredPage(): string {
  return arcadePage({
    tone: "warn",
    title: "Not signed in yet",
    lead: "This page hands an existing browser session back to the Tui CLI, and there is no session on this browser.",
    steps: [
      "Start from the terminal: <code>gamepigeon auth oauth google</code>",
      "Using GitHub instead? <code>gamepigeon auth oauth github</code>",
      "Prefer a password? <code>gamepigeon auth login</code>",
    ],
    hint: "The sign-in link opens this browser again and comes straight back here.",
  });
}

/**
 * A CLI sign-in that could not be started or handed back. `reason` is trusted
 * HTML — escape request-derived text with `escapeHtml` first.
 */
export function signInProblemPage(title: string, reason: string): string {
  return arcadePage({
    tone: "warn",
    title,
    lead: reason,
    steps: [
      "Go back to your terminal and run <code>gamepigeon auth oauth google</code> (or <code>github</code>) again.",
      "Still stuck? <code>gamepigeon auth login</code> signs in the same account with a password.",
    ],
  });
}

