 * where a session token is sent, so only a plain-http `127.0.0.1`/`localhost`
 * URL qualifies — anything else (another host, `https`, a custom scheme, a
 * `javascript:` URL) is refused before a token is attached.
 */
export function cliNextTarget(next: string | null): URL | null {
  if (!next) return null;
  let url: URL;
  try {
    url = new URL(next);
  } catch {
    return null;
  }
  if (url.protocol !== "http:") return null;
  if (url.hostname !== "127.0.0.1" && url.hostname !== "localhost") return null;
  return url;
}

