 * (e.g. the CLI's `state`). Concatenated rather than built with
 * `URLSearchParams`: the listener reads the token straight out of the query
 * without decoding it, so re-encoding the cookie value here would hand back a
 * token that no longer matches.
 */
function nextWithToken(next: URL, token: string): string {
  const base = cliNextUrl(next);
  return `${base}${next.search ? "&" : "?"}token=${token}`;
}

/**
 * The literal session cookie value, read from the request's `Cookie` header
 * rather than from what `getSession` returns: that object's shape (whether it
 * nests a raw token, and in what form) is not something this handoff should
 * depend on. Not decoded — the value is passed through verbatim.
 */
function sessionCookieToken(cookieHeader: string | null): string | null {
  if (!cookieHeader) return null;
  for (const name of sessionCookieNames) {
    for (const part of cookieHeader.split(";")) {
      const separator = part.indexOf("=");
      if (separator < 0) continue;
      if (part.slice(0, separator).trim() !== name) continue;
      const value = part.slice(separator + 1).trim();
      if (value) return value;
    }
  }
