async function callbackServer() {
  const server = startOAuthCallbackServer(0);
  await server.ready;
  return server;
}

test("callback listener answers the readiness probe", async () => {
  const server = await callbackServer();
  try {
    const response = await fetch(`http://127.0.0.1:${server.port}/auth/ping`);
    expect(response.status).toBe(200);
    expect(await response.text()).toBe("ok");

    const missing = await fetch(`http://127.0.0.1:${server.port}/elsewhere`);
    expect(missing.status).toBe(404);
  } finally {
    server.close();
  }
});

test("callback listener reads a token glued onto an existing state param", async () => {
  const server = await callbackServer();
  try {
    const response = await fetch(
      `http://127.0.0.1:${server.port}/auth/callback?state=nonce-value?token=session-secret`,
    );
    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(await response.text()).toContain("signed in");
    // Raw and unverified: the listener has no nonce to compare `state` against.
    await expect(server.token).resolves.toBe("session-secret");
  } finally {
    server.close();
  }
});

test("callback listener reports a cancelled sign-in", async () => {
  const server = await callbackServer();
  try {
    const response = await fetch(
      `http://127.0.0.1:${server.port}/auth/callback?state=nonce&error=access_denied`,
    );
    expect(response.status).toBe(400);
    expect(await response.text()).toMatch(/cancelled/i);
    await expect(server.token).rejects.toThrow(/cancelled/i);
  } finally {
    server.close();
  }
});

test("callback listener escapes a reported error before showing it", async () => {
  const server = await callbackServer();
  try {
    const description = "<script>alert(1)</script> not allowed";
    const response = await fetch(
      `http://127.0.0.1:${server.port}/auth/callback?error=server_error&error_description=${
        encodeURIComponent(description)
      }`,
    );
    expect(response.status).toBe(400);
    const body = await response.text();
    expect(body).not.toContain("<script>alert(1)</script>");
    expect(body).toContain("&lt;script&gt;alert(1)&lt;/script&gt; not allowed");
    // The terminal gets the description as the login page wrote it.
    await expect(server.token).rejects.toThrow(description);
  } finally {
    server.close();
  }
});

test("callback listener rejects a callback that carries no token at all", async () => {
  const server = await callbackServer();
  try {
    const response = await fetch(`http://127.0.0.1:${server.port}/auth/callback?state=nonce`);
    expect(response.status).toBe(400);
    await expect(server.token).rejects.toThrow(/session token/);
  } finally {
    server.close();
  }
});

test("callback listener falls back to a free port when the requested one is taken", async () => {
  const first = await callbackServer();
  try {
    const second = startOAuthCallbackServer(first.port);
    try {
      await second.ready;
      expect(second.port).not.toBe(first.port);
      expect(second.port).toBeGreaterThan(0);
      const response = await fetch(`http://127.0.0.1:${second.port}/auth/ping`);
      expect(await response.text()).toBe("ok");
    } finally {
      second.close();
    }
  } finally {
    first.close();
  }
});

test("Arc and Dia links get a real tab, other browsers do not", () => {
  expect(isArcBundle("company.thebrowser.Browser")).toBe(true);
  expect(isArcBundle("company.thebrowser.dia")).toBe(true);
  expect(isArcBundle("com.google.Chrome")).toBe(false);
  expect(isArcBundle("com.apple.Safari")).toBe(false);

  const script = arcTabScript("company.thebrowser.Browser", 'http://127.0.0.1:3210/a?b="c"\\d');
  expect(script).toContain('tell application id "company.thebrowser.Browser"');
  expect(script).toContain("make new tab with properties");
  // Quotes and backslashes in the URL must not end the AppleScript string.
  expect(script).toContain('URL:"http://127.0.0.1:3210/a?b=\\"c\\"\\\\d"');
});

test("oauth sign-in only accepts the providers the worker supports", async () => {
  await expect(runAuthCommand("oauth")).rejects.toThrow(/google\|github/);
  await expect(runAuthCommand("oauth", "facebook")).rejects.toThrow(/google\|github/);
});
EOF
