import { createServer } from "node:http";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runAuthCommand } from "/app/src/auth.ts";

const home = mkdtempSync(join(tmpdir(), "oauth-e2e-"));
process.env.HOME = home;

const auth = createServer((request, response) => {
  const url = new URL(request.url ?? "/", "http://127.0.0.1");
  if (url.pathname === "/cli/oauth") {
    console.log("[worker] provider:", url.searchParams.get("provider"));
    const next = url.searchParams.get("next")!;
    // Mimics /cli/handoff gluing the token onto the existing query.
    response.writeHead(302, { location: `${next}${next.includes("?") ? "&" : "?"}token=fake-token` });
    response.end();
    return;
  }
  if (url.pathname === "/api/auth/get-session") {
    console.log("[worker] bearer:", request.headers.authorization);
    response.writeHead(200, { "content-type": "application/json" });
    response.end(JSON.stringify({ user: { id: "usr_1", email: "person@example.com" } }));
    return;
  }
  response.writeHead(404);
  response.end();
});
await new Promise<void>((resolve) => auth.listen(0, "127.0.0.1", resolve));
const port = (auth.address() as { port: number }).port;
process.env.GAMEPIGEON_AUTH_URL = `http://127.0.0.1:${port}`;

const log = console.log;
let signInUrl = "";
console.log = (...args: unknown[]) => {
  const line = args.join(" ");
  if (line.includes("/cli/oauth?")) signInUrl = line.trim();
  log("[cli]", line);
};

const pending = runAuthCommand("oauth", "google");
while (!signInUrl) await new Promise((resolve) => setTimeout(resolve, 25));
log("browser follows:", signInUrl);
const landed = await fetch(signInUrl, { redirect: "follow" });
log("browser page:", landed.status, (await landed.text()).includes("You&#39;re signed in") ? "signed-in page" : "OTHER");
log("result:", await pending);
log("auth.json:", readFileSync(join(home, ".tui-gamepigeon", "auth.json"), "utf8"));
log("backend.conf:", JSON.stringify(readFileSync(join(home, ".tui-gamepigeon", "backend.conf"), "utf8")));
auth.close();
rmSync(home, { recursive: true, force: true });
EOF
