import { getMigrations } from "better-auth/db/migration";
import { env } from "cloudflare:workers";
import { beforeAll, expect, test } from "vitest";
import { createAuth, type AuthEnv } from "../src/auth";
import worker from "../src/index";

const origin = "https://auth.runretroarcade.com";
const listener = "http://127.0.0.1:3210/auth/callback?state=nonce";

// Enough of a client id/secret pair for `/cli/oauth` to count the provider as
// configured; no request ever leaves the Worker in these tests.
const withGoogle: AuthEnv = { ...env, GOOGLE_CLIENT_ID: "google-id", GOOGLE_CLIENT_SECRET: "google-secret" };

function get(path: string, init: RequestInit = {}, overrides: AuthEnv = env): Promise<Response> {
  return worker.fetch(new Request(`${origin}${path}`, init), overrides);
}

function cliOAuth(query: string, overrides: AuthEnv = env): Promise<Response> {
  return get(`/cli/oauth?${query}`, {}, overrides);
}

function cliHandoff(next: string, init: RequestInit = {}): Promise<Response> {
  return get(`/cli/handoff?next=${encodeURIComponent(next)}`, init);
}

beforeAll(async () => {
  const { runMigrations } = await getMigrations(createAuth(env).options);
  await runMigrations();
});

/** Signs up a browser-style session and returns its `Cookie` header. */
async function signedInCookie(email: string): Promise<string> {
  const response = await get("/api/auth/sign-up/email", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email, password: "correct-horse-battery", name: "Test Person" }),
  });
  expect(response.status).toBe(200);
  const cookies = response.headers.getSetCookie().map((cookie) => cookie.split(";")[0]);
  expect(cookies.join("; ")).toMatch(/session_token=/);
  return cookies.join("; ");
}

test("only google and github can start a CLI sign-in", async () => {
  for (const provider of ["facebook", "", "GOOGLE ", "apple"]) {
    const response = await cliOAuth(
      `provider=${encodeURIComponent(provider)}&next=${encodeURIComponent(listener)}`,
      withGoogle,
    );
    expect(response.status).toBe(400);
  }
  const missing = await cliOAuth(`next=${encodeURIComponent(listener)}`, withGoogle);
  expect(missing.status).toBe(400);
});

test("a supported provider with no credentials configured is unavailable, not invalid", async () => {
  const google = await cliOAuth(`provider=google&next=${encodeURIComponent(listener)}`);
  expect(google.status).toBe(503);
  const github = await cliOAuth(`provider=github&next=${encodeURIComponent(listener)}`);
  expect(github.status).toBe(503);
  // Configuration is checked before `next`, so a broken link on an unconfigured
  // provider still reports the thing an operator has to fix.
  const both = await cliOAuth("provider=google&next=https://evil.example/steal");
  expect(both.status).toBe(503);
});

test("/cli/oauth refuses to send a sign-in anywhere but loopback http", async () => {
  const targets = [
    "https://evil.example/steal",
    "https://127.0.0.1:3210/auth/callback",
    "http://127.0.0.1.evil.example/auth/callback",
    "http://localhost.evil.example/auth/callback",
    "javascript:alert(1)",
    "file:///etc/passwd",
    "/auth/callback",
    "",
  ];
  for (const next of targets) {
    const response = await cliOAuth(
      `provider=google&next=${encodeURIComponent(next)}`,
      withGoogle,
    );
    expect(response.status, next).toBe(400);
  }
});

test("a configured provider redirects onward with its state cookie", async () => {
  const response = await cliOAuth(`provider=google&next=${encodeURIComponent(listener)}`, withGoogle);
  expect(response.status).toBe(302);
  const location = response.headers.get("location") ?? "";
  expect(location.startsWith("https://accounts.google.com/")).toBe(true);
  // The provider sends the browser back to the Worker, not straight to the CLI:
  // only a request that carries the session cookie can hand a token over.
  const redirectUri = new URL(location).searchParams.get("redirect_uri") ?? "";
  expect(redirectUri).toBe(`${origin}/api/auth/callback/google`);
  expect(response.headers.getSetCookie().join("; ")).toMatch(/state/);
  expect(response.headers.get("cache-control")).toBe("no-store");
});

test("/cli/handoff refuses a next target that isn't loopback http", async () => {
  for (const next of ["https://evil.example/steal", "http://127.0.0.1.evil.example/", "wss://127.0.0.1/"]) {
    const response = await cliHandoff(next, { headers: { cookie: "better-auth.session_token=whatever" } });
    expect(response.status, next).toBe(400);
    expect(await response.text()).not.toContain("whatever");
  }
  const missing = await get("/cli/handoff");
  expect(missing.status).toBe(400);
});

test("/cli/handoff without a browser session says how to start one", async () => {
  const response = await cliHandoff(listener);
  expect(response.status).toBe(401);
  expect((await response.text()).toLowerCase()).toContain("oauth");
});

test("/cli/handoff hands the session cookie back on the next URL's query", async () => {
  const cookie = await signedInCookie("handoff@example.com");
  const token = cookie.match(/session_token=([^;]+)/)?.[1];
  expect(token).toBeTruthy();

  const response = await cliHandoff(listener, { headers: { cookie } });
  expect(response.status).toBe(200);
  expect(response.headers.get("cache-control")).toBe("no-store");
  const body = await response.text();
  // Literal and un-escaped so the redirect script sends the browser to exactly
  // the URL the CLI listener parses, `state` included.
  expect(body).toContain(`http://127.0.0.1:3210/auth/callback?state=nonce&token=${token}`);
  expect(body).toContain("location.replace(");

  // A `next` with no query of its own starts one.
  const bare = await cliHandoff("http://localhost:51234/auth/callback", { headers: { cookie } });
  expect(await bare.text()).toContain(`http://localhost:51234/auth/callback?token=${token}`);
});
